{
    "_version": "1.32.0",
    "sap.app": {
        "id": "mif.rmd.configuracion",
        "type": "application",
        "i18n": "i18n/i18n.properties",
        "applicationVersion": {
            "version": "1.0.0"
        },
        "title": "{{appTitle}}",
        "description": "{{appDescription}}",
        "resources": "resources.json",
        "ach": "ach",
        "dataSources": {
            "mainService": {
                "uri": "/api/base/rmd/browse/",
                "type": "OData",
                "settings": {
                    "odataVersion": "4.0",
                    "localUri": "localService/metadata.xml"
                }
            },
            "mainServicev2": {
                "uri": "/api/base/rmd/v2/browse/",
                "type": "OData",
                "settings": {
                    "odataVersion": "2.0",
                    "localUri": "localService/metadata.xml"
                }
            },
            "PRODUCCION_SRV": {
                "uri": "/api/integracion/saperp/rmd/sap/opu/odata/sap/Z_PP_PRODUCCION_SRV/",
                "type": "OData",
                "settings": {
                    "localUri": "localService/Z_PP_PRODUCCION_SRV/metadata.xml"
                }
            },
            "NECESIDADESRMD_SRV": {
                "uri": "/api/integracion/saperp/rmd/sap/opu/odata/sap/Z_PP_NECESIDADESRMD_SRV/",
                "type": "OData",
                "settings": {
                    "localUri": "localService/Z_PP_NECESIDADESRMD_SRV/metadata.xml"
                }
            }
        },
        "crossNavigation": {
            "inbounds": {
                "mif-rmd-configuracion-inbound": {
                    "signature": {
                        "parameters": {},
                        "additionalParameters": "allowed"
                    },
                    "semanticObject": "configuracion",
                    "action": "display",
                    "title": "{{flpTitle}}",
                    "subTitle": "{{flpSubtitle}}",
                    "icon": "sap-icon://add-equipment"
                }
            }
        }
    },
    "sap.ui": {
        "technology": "UI5",
        "icons": {
            "icon": "sap-icon://task",
            "favIcon": "",
            "phone": "",
            "phone@2": "",
            "tablet": "",
            "tablet@2": ""
        },
        "deviceTypes": {
            "desktop": true,
            "tablet": true,
            "phone": true
        }
    },
    "sap.ui5": {
        "flexEnabled": false,
        "rootView": {
            "viewName": "mif.rmd.configuracion.view.MainView",
            "type": "XML",
            "async": true,
            "id": "MainView"
        },
        "dependencies": {
            "minUI5Version": "1.84.50",
            "libs": {
                "sap.ui.core": {},
                "sap.m": {},
                "sap.ui.layout": {},
                "sap.f": {}
            }
        },
        "contentDensities": {
            "compact": true,
            "cozy": true
        },
        "models": {
            "i18n": {
                "type": "sap.ui.model.resource.ResourceModel",
                "settings": {
                    "bundleName": "mif.rmd.configuracion.i18n.i18n"
                }
            },
            "localModel": {
                "type": "sap.ui.model.json.JSONModel",
                "uri": "model/localModel.json"
            },
            "mainModel": {
                "dataSource": "mainService",
                "preload": true,
                "settings": {
                    "operationMode": "Server",
                    "groupId": "$direct",
                    "synchronizationMode": "None",
                    "autoExpandSelect": true,
                    "updateGroupId": "updateGroup"
                }
            },
            "mainModelv2": {
                "dataSource": "mainServicev2",
                "preload": true,
                "settings": {

{
  "welcomeFile": "/index.html",
  "authenticationMethod": "route",
  "routes": [{
		"source": "^/bpmworkflowruntime/(.*)$",
		"target": "/$1",
		"service": "com.sap.bpm.workflow",
		"endpoint": "workflow_rest_url",
		"authenticationType": "xsuaa"
    },
    {
        "source": "^/srv_api/(.*)$",
        "target": "$1",
        "authenticationType": "none",
        "destination": "RMD_BTP_HTTP",
        "csrfProtection": false
    },
    {
        "source": "^/saperp/(.*)$",
        "target": "$1",
        "authenticationType": "none",
        "destination": "RMD_S4H_HTTP_BASIC",
        "csrfProtection": false
    },
    {
        "source": "^/scimApi/(.*)$",
        "target": "$1",
        "authenticationType": "none",
        "destination": "IAS_SCIM_API",
        "csrfProtection": false
    },
    {
        "source": "^/IAS_API/(.*)$",
        "target": "$1",
        "authenticationType": "none",
        "destination": "IAS_API",
        "csrfProtection": false
    },
    {
      "authenticationType": "xsuaa",
      "csrfProtection": false,
      "source": "^/dest-apigateway/(.*)$",
      "destination": "dest-apigateway",
      "target": "$1"
    },
    {
      "authenticationType": "xsuaa",
      "csrfProtection": false,
      "source": "^/dest-apiseguridad/(.*)$",
      "destination": "dest-apiseguridad",
      "target": "$1"
    },
    {
      "source": "^/resources/(.*)$",
      "target": "/resources/$1",
      "authenticationType": "none",
      "destination": "ui5"
    },
    {
      "source": "^/test-resources/(.*)$",
      "target": "/test-resources/$1",
      "authenticationType": "none",
      "destination": "ui5"
    },
    {
      "source": "^(.*)$",
      "target": "$1",
      "service": "html5-apps-repo-rt",
      "authenticationType": "xsuaa",
      "cacheControl": "no-cache, no-store, must-revalidate"
    }
  ]
}

